-- Additive IAM grants: 4547baa -> 0e89d44 (generated by scripts/gen-permission-grants.ts --since 4547baa).
-- Idempotent (every insert is NOT EXISTS-guarded); one transaction. Apply with psql -v ON_ERROR_STOP=1
-- against the RawProd MAIN database as the owner (DDL/DML) role. Never instead of this: pnpm db:seed.
-- New permission codes (0): none
-- New roles (0): none
-- New grants (5):
--   procurement            platform:print_job:write
--   receiving              platform:print_job:read
--   receiving              platform:print_job:write
--   qc                     platform:print_job:read
--   qc                     platform:print_job:write

begin;

insert into iam.role_permission_mapping (role_id, permission_id, status, created_by, updated_by)
select r.role_id, p.permission_id, 'ACTIVE', 'release-grant', 'release-grant'
  from (values
    ('procurement', 'platform:print_job:write'),
    ('receiving', 'platform:print_job:read'),
    ('receiving', 'platform:print_job:write'),
    ('qc', 'platform:print_job:read'),
    ('qc', 'platform:print_job:write')
  ) as g(role_code, permission_code)
  join iam.role_master r on r.role_code = g.role_code
  join iam.permission_master p on p.permission_code = g.permission_code
 where not exists (select 1 from iam.role_permission_mapping m where m.role_id = r.role_id and m.permission_id = p.permission_id);

commit;
